import numpy as np

def step(lam,w,s):
    # w squared error directions
    V=np.array([lam**j for j in range(1,s+1)]).T
    c=np.linalg.solve(V.T@(w[:,None]*V),-V.T@w)
    p=1+V@c
    f=w@(p*p)
    return w*p*p/f, p, f
