    lam=np.sort(rng.uniform(.1,2,n)); w=rng.dirichlet(np.ones(n)); prev=None
    for k in range(5000):
     w,p,f=step(lam,w,s)
     if k==3999: prev=w.copy()
    dif=np.linalg.norm(w-prev)
    if dif>best: best=dif; record=(lam,w,f)
   print(s,n,best,record,flush=True)

