def step(w,a=2.,b=1.):
 # nodes [-a,-b,b,a], translating leaves monic orthogonal polynomial invariant
 z=np.array([-a,-b,b,a]); z2=z*z
 m1=w@z;m2=w@z2;m3=w@(z2*z)
 c1=(m1*m2-m3)/(m2-m1*m1); c0=-m2-c1*m1
 p=z2+c1*z+c0
 return w*p*p/(w@(p*p)), c1,c0

